"""Extra independent checks: different seeds + adversarial carry search."""
import random, itertools
from problems import ExactCover, SubsetSum
from reduce import reduce
from test_reduce import exact_cover_brute, subset_sum_brute

total = 0
passed = 0
fails = []

def check(inst, tag):
    global total, passed
    total += 1
    ExactCover.validate(inst)
    out = reduce(inst)
    SubsetSum.validate(out)
    if exact_cover_brute(inst) == subset_sum_brute(out):
        passed += 1
    else:
        fails.append((tag, inst, out))

# many seeds
for seed in range(50):
    rng = random.Random(seed)
    for i in range(400):
        u = rng.randint(0, 6)
        m = rng.randint(0, 7)
        sets = [[e for e in range(u) if rng.random() < rng.choice([0.3,0.5,0.7])] for _ in range(m)]
        check({"universe_size": u, "sets": sets}, f"seed{seed}-{i}")

# adversarial: many duplicate/overlapping sets designed to stress carries
for u in range(1, 5):
    subs = []
    for r in range(u+1):
        for c in itertools.combinations(range(u), r):
            subs.append(list(c))
    for m in range(1, 5):
        for choice in itertools.product(subs, repeat=m):
            check({"universe_size": u, "sets": [list(c) for c in choice]}, f"adv u={u} m={m}")

# targeted: u=5 with up to 3 sets (carry stress with duplicates)
u = 5
subs = []
for r in range(u+1):
    for c in itertools.combinations(range(u), r):
        subs.append(list(c))
for m in range(1, 4):
    for choice in itertools.product(subs, repeat=m):
        check({"universe_size": u, "sets": [list(c) for c in choice]}, f"adv5 u={u} m={m}")

print(f"extra total={total} passed={passed} fails={len(fails)}")
for f in fails[:10]:
    print(f)
EOF
